BEGIN;

CREATE TABLE IF NOT EXISTS public.game (
    slug TEXT PRIMARY KEY REFERENCES public.pokemon(slug),
    caps TEXT[] NOT NULL DEFAULT '{}',
    dicas JSONB NOT NULL DEFAULT '{}'::jsonb,
    images JSONB NOT NULL DEFAULT '{}'::jsonb
);

ALTER TABLE public.game
    ADD COLUMN IF NOT EXISTS categorias JSONB NOT NULL DEFAULT '{}'::jsonb;

INSERT INTO public.game (slug)
VALUES ('pokemon-blue')
ON CONFLICT (slug) DO NOTHING;

-- Registros disponíveis para todos os jogos cadastrados em game.
INSERT INTO public.game (slug)
SELECT slug FROM public.pokemon
ON CONFLICT (slug) DO NOTHING;

-- Pós-game aprovado dos jogos de Kanto.
WITH capitulos (ordem, titulo, passos) AS (
VALUES
(1, 'Articuno', ARRAY['Siga até Fuchsia City e use Surf ao sul pela Route 19, depois continue pela Route 20 até chegar às Seafoam Islands.', 'Dentro da caverna, use Strength para empurrar as pedras pelos buracos e alterar as correntezas, depois procure o caminho até Articuno.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.']),
(2, 'Zapdos', ARRAY['Volte à Route 10, perto da entrada do Rock Tunnel, e use Surf na água para seguir até a Power Plant.', 'Entre na usina e avance pelas salas até encontrar Zapdos.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.']),
(3, 'Moltres', ARRAY['Volte à Victory Road e atravesse a caverna até encontrar Moltres.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.']),
(4, 'Mewtwo', ARRAY['Depois de se tornar Champion, volte a Cerulean City e siga ao norte pela ponte, depois use Surf na água a oeste para chegar à entrada da Cerulean Cave.', 'Explore os andares da caverna e siga até a parte mais profunda, onde encontrará Mewtwo.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'])
), guia AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS dicas FROM capitulos
)
INSERT INTO public.game (slug, caps, dicas)
SELECT pokemon.slug, guia.caps, guia.dicas FROM public.pokemon AS pokemon CROSS JOIN guia
WHERE pokemon.slug IN ('pokemon-red', 'pokemon-green', 'pokemon-blue', 'pokemon-yellow')
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

WITH capitulos (ordem, titulo, passos) AS (
VALUES
(1, 'Articuno', ARRAY['Siga até Fuchsia City e use Sea Skim ao sul pela Route 19, depois continue pela Route 20 até chegar às Seafoam Islands.', 'Dentro da caverna, use Strong Push para mover as pedras e abrir caminho até Articuno.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.', 'Ao vencer a batalha, use suas Poké Balls para tentar capturá-lo.']),
(2, 'Zapdos', ARRAY['Volte à Route 10, perto da entrada do Rock Tunnel, e use Sea Skim na água para seguir até a Power Plant.', 'Entre na usina e avance pelas salas até encontrar Zapdos.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.', 'Ao vencer a batalha, use suas Poké Balls para tentar capturá-lo.']),
(3, 'Moltres', ARRAY['Volte à Victory Road e atravesse a caverna até encontrar Moltres.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.', 'Ao vencer a batalha, use suas Poké Balls para tentar capturá-lo.']),
(4, 'Mewtwo', ARRAY['Depois de se tornar Champion, volte a Cerulean City e siga ao norte pela ponte, depois use Sea Skim na água a oeste para chegar à entrada da Cerulean Cave.', 'Explore os andares da caverna e siga até a parte mais profunda, onde encontrará Mewtwo.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.', 'Ao vencer a batalha, use suas Poké Balls para tentar capturá-lo.'])
), guia AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS dicas FROM capitulos
)
INSERT INTO public.game (slug, caps, dicas)
SELECT pokemon.slug, guia.caps, guia.dicas FROM public.pokemon AS pokemon CROSS JOIN guia
WHERE pokemon.slug IN ('pokemon-let-s-go-pikachu', 'pokemon-let-s-go-eevee')
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

WITH capitulos (ordem, titulo, passos) AS (
VALUES
(1, 'Sevii Islands', ARRAY['Depois de se tornar Champion, volte ao laboratório do Professor Carvalho em Pallet Town com pelo menos 60 espécies registradas como capturadas para receber a National Pokédex.', 'Vá ao porto de Vermilion City e viaje até One Island, depois encontre Celio no Pokémon Center e converse com ele sobre sua máquina.', 'Siga ao Mt. Ember e derrote os membros da Team Rocket diante da entrada de uma caverna, depois entre e avance até encontrar o Ruby.', 'Entregue o Ruby a Celio para receber o Rainbow Pass e liberar a viagem para mais ilhas.', 'Em Four Island, entre na Icefall Cave e encontre o HM07 Waterfall, depois ajude Lorelei a enfrentar a Team Rocket.', 'Siga para Six Island e procure a Dotted Hole no Ruin Valley, depois use Cut na porta e desça pelos buracos até encontrar o Sapphire.', 'Um cientista da Team Rocket pegará o Sapphire antes de você, então siga até o Rocket Warehouse em Five Island e enfrente a equipe para recuperá-lo.', 'Volte a One Island e entregue o Sapphire a Celio para concluir o trabalho na máquina.']),
(2, 'Articuno', ARRAY['Siga até Fuchsia City e use Surf ao sul pela Route 19, depois continue pela Route 20 até chegar às Seafoam Islands.', 'Dentro da caverna, use Strength para empurrar as pedras pelos buracos e alterar as correntezas, depois procure o caminho até Articuno.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.']),
(3, 'Zapdos', ARRAY['Volte à Route 10, perto da entrada do Rock Tunnel, e use Surf na água para seguir até a Power Plant.', 'Entre na usina e avance pelas salas até encontrar Zapdos.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.']),
(4, 'Moltres', ARRAY['Viaje até One Island e siga pela Kindle Road até o Mt. Ember.', 'Suba a montanha e use Strength para mover as pedras que bloqueiam o caminho até Moltres.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.']),
(5, 'Mewtwo', ARRAY['Depois de entregar o Ruby e o Sapphire a Celio, volte a Cerulean City e siga ao norte pela ponte.', 'Use Surf na água a oeste para chegar à entrada da Cerulean Cave, depois explore a caverna até encontrar Mewtwo em sua parte mais profunda.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.']),
(6, 'Raikou, Entei ou Suicune', ARRAY['Depois de ajudar Celio com o Ruby e o Sapphire, um dos três lendários começará a percorrer as rotas de Kanto, de acordo com o Pokémon que você escolheu no início da jornada.', 'Se você escolheu Bulbasaur, encontrará Entei. Se escolheu Charmander, encontrará Suicune. Se escolheu Squirtle, encontrará Raikou.', 'Prepare sua equipe e procure o lendário pela grama das rotas de Kanto, lembrando que ele pode fugir da batalha e mudar de localização.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.', 'Após encontrá-lo pela primeira vez, consulte sua localização na Pokédex para continuar a perseguição caso ele escape.'])
), guia AS (
 SELECT array_agg(titulo ORDER BY ordem) AS caps, jsonb_object_agg(titulo, to_jsonb(passos)) AS dicas FROM capitulos
)
INSERT INTO public.game (slug, caps, dicas)
SELECT pokemon.slug, guia.caps, guia.dicas FROM public.pokemon AS pokemon CROSS JOIN guia
WHERE pokemon.slug IN ('pokemon-fire-red', 'pokemon-leaf-green')
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

-- Pós-game de Johto, com capítulos compartilhados e exclusivos por versão.
WITH capitulos_johto (ordem, titulo, passos, jogos) AS (
VALUES
(10, 'S.S. Aqua', ARRAY['Depois de se tornar Champion, volte a New Bark Town e visite o Professor Elm para receber o S.S. Ticket.', 'Siga para o porto de Olivine City e embarque no S.S. Aqua em direção a Kanto.', 'Durante a viagem, ajude um passageiro a encontrar sua neta e converse com o capitão, depois volte ao avô da menina e espere o navio chegar a Vermilion City.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(20, 'Vermilion City', ARRAY['Ao chegar a Vermilion City, entre no ginásio e enfrente Lt. Surge, líder especialista no tipo Elétrico.', 'Depois de conquistar a Thunder Badge, siga ao norte pela Route 6 até Saffron City.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(30, 'Saffron City', ARRAY['Em Saffron City, entre no ginásio e use os teletransportadores para encontrar Sabrina.', 'Derrote a líder especialista no tipo Psíquico para conquistar a Marsh Badge, depois siga para oeste até Celadon City.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(40, 'Celadon City', ARRAY['Em Celadon City, entre no ginásio e enfrente Erika, líder especialista no tipo Planta, para conquistar a Rainbow Badge.', 'Depois da vitória, siga para Fuchsia City pelas rotas ao sul de Lavender ou pelo caminho a oeste de Celadon.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(50, 'Fuchsia City', ARRAY['Entre no ginásio de Fuchsia e atravesse o labirinto até encontrar Janine, filha de Koga e nova líder da cidade.', 'Derrote a especialista no tipo Veneno para conquistar a Soul Badge, depois siga até Lavender Town.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(60, 'Power Plant', ARRAY['De Lavender Town, siga ao norte pela Route 10 e use Surf para chegar à Power Plant.', 'Converse com o responsável pela usina e descubra que uma peça foi roubada, depois siga para Cerulean City.', 'Entre no ginásio de Cerulean e encontre o membro da Team Rocket, depois siga para a Route 24 e enfrente-o para descobrir onde a peça foi escondida.', 'Volte ao ginásio e procure a Machine Part perto da piscina, depois entregue-a na Power Plant para restaurar a energia.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(70, 'Cerulean City', ARRAY['Depois de resolver o problema da Power Plant, siga para o norte de Cerulean e atravesse as Routes 24 e 25 até encontrar Misty.', 'Converse com ela para que volte ao ginásio, depois retorne à cidade e enfrente a líder especialista no tipo Água para conquistar a Cascade Badge.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(80, 'Pewter City', ARRAY['Siga para Pewter City e entre no ginásio para enfrentar Brock, líder especialista no tipo Pedra.', 'Depois de conquistar a Boulder Badge, converse com o senhor da cidade para receber uma asa importante para encontrar um dos lendários de Johto.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(90, 'Cinnabar Island', ARRAY['Siga para Cinnabar Island e encontre Blue, que contará sobre a destruição causada pela erupção do vulcão.', 'Use Surf para seguir até as Seafoam Islands e encontre o ginásio de Blaine dentro da caverna.', 'Derrote o líder especialista no tipo Fogo para conquistar a Volcano Badge, depois siga para Viridian City.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(100, 'Viridian City', ARRAY['Com as outras sete insígnias de Kanto em mãos, entre no ginásio de Viridian e enfrente Blue.', 'Depois de derrotá-lo, receba a Earth Badge e complete suas 16 insígnias.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal', 'pokemon-heart-gold', 'pokemon-soul-silver']),
(110, 'Mt. Silver', ARRAY['Com todas as insígnias, visite o Professor Carvalho em Pallet Town para liberar o acesso ao Mt. Silver.', 'Siga para oeste de Viridian City e atravesse a passagem que leva à Route 28, depois continue até o Mt. Silver.', 'Atravesse a montanha até encontrar Red e enfrente sua equipe para concluir o maior desafio da jornada.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal']),
(110, 'Mt. Silver', ARRAY['Com todas as insígnias, visite o Professor Carvalho em Pallet Town para liberar o acesso ao Mt. Silver.', 'Receba também o HM08 Rock Climb do Professor Carvalho para chegar ao topo da montanha.', 'Siga para oeste de Viridian City e atravesse a passagem que leva à Route 28, depois continue até o Mt. Silver.', 'Atravesse a montanha até encontrar Red e enfrente sua equipe para concluir o maior desafio da jornada.'], ARRAY['pokemon-heart-gold', 'pokemon-soul-silver']),
(11, 'Raikou e Entei', ARRAY['Depois de encontrar os lendários na Burned Tower em Ecruteak City, Raikou e Entei passam a percorrer as rotas de Johto.', 'Procure-os na grama e, após encontrá-los pela primeira vez, consulte a Pokédex para acompanhar suas localizações.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-gold', 'pokemon-silver', 'pokemon-crystal']),
(11, 'Raikou e Entei', ARRAY['Depois de encontrar os lendários na Burned Tower em Ecruteak City, Raikou e Entei passam a percorrer as rotas de Johto.', 'Consulte o mapa do Pokégear para acompanhar suas localizações e procure-os na grama das rotas.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold', 'pokemon-soul-silver']),
(12, 'Suicune', ARRAY['Suicune também percorre as rotas de Johto após o encontro na Burned Tower.', 'Procure-o na grama e consulte a Pokédex depois de encontrá-lo pela primeira vez para acompanhar sua localização.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-gold', 'pokemon-silver']),
(12, 'Suicune', ARRAY['Depois de receber o Clear Bell na Radio Tower, siga até a Tin Tower em Ecruteak City, derrote os sábios e encontre Suicune.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-crystal']),
(71, 'Suicune', ARRAY['Após encontrá-lo na Burned Tower, procure Suicune ao norte de Cianwood City e depois na Route 42, perto do Mt. Mortar.', 'Em Kanto, encontre-o em Vermilion City e na Route 14, depois siga para a Route 25, perto da casa de Bill, após Misty voltar ao ginásio.', 'Encontre Suicune na Route 25 para a batalha.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold', 'pokemon-soul-silver']),
(81, 'Lugia', ARRAY['Receba a Silver Wing do senhor em Pewter City antes de seguir para as Whirl Islands.', 'Use Surf e Whirlpool para entrar nas Whirl Islands, depois atravesse a caverna até encontrar Lugia.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-gold', 'pokemon-crystal', 'pokemon-heart-gold']),
(81, 'Lugia', ARRAY['Use a Silver Wing recebida após os acontecimentos na Radio Tower e siga até as Whirl Islands.', 'Use Surf e Whirlpool para entrar nas Whirl Islands, depois atravesse a caverna até encontrar Lugia.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-silver']),
(81, 'Lugia', ARRAY['Use a Silver Wing recebida durante a campanha e siga até as Whirl Islands.', 'Use Surf e Whirlpool para entrar nas Whirl Islands, depois atravesse a caverna até encontrar Lugia.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-soul-silver']),
(82, 'Ho-Oh', ARRAY['Use a Rainbow Wing recebida após os acontecimentos na Radio Tower e siga até a Tin Tower em Ecruteak City.', 'Atravesse os andares da torre até encontrar Ho-Oh no topo.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-gold']),
(82, 'Ho-Oh', ARRAY['Receba a Rainbow Wing do senhor em Pewter City antes de subir a Tin Tower em Ecruteak City.', 'Atravesse os andares da torre até encontrar Ho-Oh no topo.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-silver']),
(82, 'Ho-Oh', ARRAY['Capture Raikou, Entei e Suicune e fale com os sábios na Tin Tower para receber a Rainbow Wing.', 'Atravesse os andares da torre até encontrar Ho-Oh no topo.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-crystal']),
(82, 'Ho-Oh', ARRAY['Siga até a Bell Tower em Ecruteak City com a Rainbow Wing recebida durante a campanha.', 'Atravesse os andares da torre até encontrar Ho-Oh no topo.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold']),
(82, 'Ho-Oh', ARRAY['Receba a Rainbow Wing do senhor em Pewter City antes de subir a Bell Tower em Ecruteak City.', 'Atravesse os andares da torre até encontrar Ho-Oh no topo.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-soul-silver']),
(91, 'Articuno', ARRAY['Siga até as Seafoam Islands e explore a caverna até encontrar Articuno.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold', 'pokemon-soul-silver']),
(101, 'Zapdos', ARRAY['Depois de conquistar as oito insígnias de Kanto, siga para a Route 10 e encontre Zapdos do lado de fora da Power Plant.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold', 'pokemon-soul-silver']),
(111, 'Moltres', ARRAY['Depois de conseguir acesso ao Mt. Silver, explore a montanha até encontrar Moltres em uma das áreas da caverna.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold', 'pokemon-soul-silver']),
(102, 'Mewtwo', ARRAY['Com as oito insígnias de Kanto, volte a Cerulean City e use Surf ao norte da cidade para chegar à Cerulean Cave.', 'Atravesse a caverna até encontrar Mewtwo em sua parte mais profunda.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold', 'pokemon-soul-silver']),
(31, 'Latias', ARRAY['Depois de obter a National Pokédex, fale com a Copycat em Saffron City e procure sua boneca perdida no Pokémon Fan Club de Vermilion City.', 'Ao sair do prédio, encontre Steven, que contará sobre Latias percorrendo Kanto.', 'Consulte o mapa do Pokégear para acompanhar sua localização.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold']),
(31, 'Latios', ARRAY['Depois de obter a National Pokédex, fale com a Copycat em Saffron City e procure sua boneca perdida no Pokémon Fan Club de Vermilion City.', 'Ao sair do prédio, encontre Steven, que contará sobre Latios percorrendo Kanto.', 'Consulte o mapa do Pokégear para acompanhar sua localização.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-soul-silver']),
(112, 'Kyogre', ARRAY['Depois de derrotar Red, visite Mr. Pokémon na Route 30 para receber o Blue Orb.', 'Siga para a Route 47 e encontre a Embedded Tower, onde estará Kyogre.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold']),
(112, 'Groudon', ARRAY['Depois de derrotar Red, visite Mr. Pokémon na Route 30 para receber o Red Orb.', 'Siga para a Route 47 e encontre a Embedded Tower, onde estará Groudon.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-soul-silver']),
(113, 'Rayquaza', ARRAY['Para encontrar Rayquaza, reúna Kyogre e Groudon capturados em HeartGold e SoulSilver, trocando com outro jogo para conseguir o lendário que falta.', 'Mostre os dois ao Professor Carvalho para receber o Jade Orb, depois volte à Embedded Tower na Route 47.', 'Encontre Rayquaza dentro da torre.', 'Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.'], ARRAY['pokemon-heart-gold', 'pokemon-soul-silver'])
), guia_johto AS (
 SELECT pokemon.slug, array_agg(capitulo.titulo ORDER BY capitulo.ordem) AS caps,
        jsonb_object_agg(capitulo.titulo, to_jsonb(capitulo.passos)) AS dicas
 FROM public.pokemon AS pokemon
 JOIN capitulos_johto AS capitulo ON pokemon.slug = ANY(capitulo.jogos)
 GROUP BY pokemon.slug
)
INSERT INTO public.game (slug, caps, dicas)
SELECT slug, caps, dicas FROM guia_johto
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

-- Categoria dos capítulos para separar lendários do pós-game.
UPDATE public.game AS jogo
SET categorias = jogo.categorias || COALESCE((
    SELECT jsonb_object_agg(capitulo.titulo,
        CASE WHEN capitulo.titulo IN (
            'Articuno', 'Zapdos', 'Moltres', 'Mewtwo',
            'Raikou, Entei ou Suicune', 'Raikou e Entei', 'Suicune', 'Lugia', 'Ho-Oh',
            'Latias', 'Latios', 'Kyogre', 'Groudon', 'Rayquaza'
        ) THEN 'lendarios' ELSE 'pos-game' END)
    FROM unnest(jogo.caps) AS capitulo(titulo)
    WHERE NOT (jogo.categorias ? capitulo.titulo)
), '{}'::jsonb)
WHERE EXISTS (
    SELECT 1 FROM unnest(jogo.caps) AS capitulo(titulo)
    WHERE NOT (jogo.categorias ? capitulo.titulo)
);

-- Pós-game de Hoenn. Somente preenche registros ainda vazios.
WITH guias_hoenn (slug, caps, dicas, categorias) AS (
VALUES
('pokemon-ruby',ARRAY['Rayquaza','Regirock','Regice','Registeel','Latios','S.S. Tidal','Battle Tower','Beldum'],'{"Rayquaza": ["Siga para leste de Pacifidlog Town pela Route 131 até encontrar a Sky Pillar. Em Ruby e Sapphire, a torre abre depois de você se tornar Champion.", "Suba a torre usando a Mach Bike para atravessar os pisos rachados e encontre Rayquaza no topo. Em Emerald, você pode voltar depois dos acontecimentos de Sootopolis City.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regirock": ["Para abrir as cavernas dos Regis, leve Relicanth e Wailord na equipe, além de Pokémon que conheçam Surf, Dive e Dig.", "Saia de Pacifidlog Town para oeste e atravesse as correntes até encontrar o ponto de mergulho da Route 134. Use Dive, siga até a inscrição e use Dive novamente para chegar à Sealed Chamber.", "Na parede ao fundo, use Dig para abrir a passagem. Coloque Relicanth na primeira posição da equipe e Wailord na última. Examine a inscrição da segunda sala para abrir as três cavernas.", "Vá às Desert Ruins, no deserto da Route 111. Leia a inscrição, dê dois passos para a direita, dois para baixo e use Strength para abrir a passagem até Regirock.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regice": ["Depois de abrir as cavernas na Sealed Chamber, use Surf na Route 105 até encontrar a Island Cave.", "Leia a inscrição e espere parado por cerca de dois minutos para abrir a passagem até Regice.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Registeel": ["Depois de abrir as cavernas na Sealed Chamber, vá até a Ancient Tomb na Route 120.", "Dentro da caverna, use Fly no centro da sala e entre pela passagem para encontrar Registeel.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Latios": ["Depois de se tornar Champion, assista à notícia na televisão em sua casa, em Littleroot Town. Latios começará a percorrer as rotas de Hoenn.", "Procure-o na grama e consulte a Pokédex depois de encontrá-lo pela primeira vez para acompanhar sua localização. Ele pode fugir da batalha, então prepare sua equipe para impedir a fuga.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "S.S. Tidal": ["Depois de se tornar Champion, volte para casa em Littleroot Town e converse com seu pai para receber o S.S. Ticket.", "Com o ticket, vá ao porto de Slateport City ou Lilycove City para embarcar no S.S. Tidal."], "Battle Tower": ["Embarque no S.S. Tidal e siga para a Battle Tower. Lá, você poderá enfrentar treinadores em batalhas consecutivas e testar sua equipe em novos desafios."], "Beldum": ["Vá até a casa de Steven em Mossdeep City e interaja com a Poké Ball que ele deixou para receber Beldum."]}'::jsonb,'{"Rayquaza": "lendarios", "Regirock": "lendarios", "Regice": "lendarios", "Registeel": "lendarios", "Latios": "lendarios", "S.S. Tidal": "pos-game", "Battle Tower": "pos-game", "Beldum": "pos-game"}'::jsonb),
