('pokemon-platinum',ARRAY['Uxie','Azelf','Mesprit','Giratina','Cresselia','Heatran','Regigigas','Dialga e Palkia','Articuno, Zapdos e Moltres','National Pokédex','Fight Area','Survival Area','Stark Mountain','Resort Area','Battle Frontier'],'{"Uxie": ["Depois dos acontecimentos na Spear Pillar, volte para Snowpoint City e siga para oeste até o Lake Acuity.", "Use Surf para chegar à ilha no centro do lago, entre na Acuity Cavern e encontre Uxie.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Azelf": ["Depois dos acontecimentos na Spear Pillar, siga para o Lake Valor, entre Veilstone City e Pastoria City.", "Use Surf para chegar à ilha no centro do lago, entre na Valor Cavern e encontre Azelf.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Mesprit": ["Depois dos acontecimentos na Spear Pillar, volte para Twinleaf Town e siga até o Lake Verity.", "Use Surf para chegar à ilha no centro do lago e entre na Verity Cavern. Ao conversar com Mesprit, ele deixará a caverna e começará a percorrer as rotas de Sinnoh.", "Use o aplicativo Marking Map do Pokétch para acompanhar sua localização e prepare sua equipe para impedir sua fuga.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Giratina": ["Giratina é enfrentado durante a campanha no Distortion World. Se você não o capturou, volte à Turnback Cave depois da Liga para encontrá-lo novamente.", "Siga pela Route 214 até Sendoff Spring, entre na Turnback Cave e procure as três colunas para chegar a Giratina.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Cresselia": ["Depois de se tornar Champion e receber a National Pokédex, vá até a casa do marinheiro em Canalave City e converse com a família dele.", "Fale com o marinheiro no porto para viajar até Fullmoon Island. Encontre Cresselia, pegue a Lunar Feather e entregue-a à família.", "Cresselia começará a percorrer as rotas de Sinnoh. Use o Marking Map do Pokétch para acompanhar sua localização.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Heatran": ["Depois de se tornar Champion e receber a National Pokédex, viaje de Snowpoint City para a Fight Area e siga pelas rotas ao norte até chegar à Stark Mountain.", "Dentro da montanha, avance ao lado de Buck até encontrar a Magma Stone. Depois dos acontecimentos, volte para a Survival Area e converse com ele.", "Retorne à sala onde encontrou a Magma Stone para encontrar Heatran.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regigigas": ["Depois de receber a National Pokédex, vá para Snowpoint City e entre no Snowpoint Temple, ao norte da cidade.", "Para despertar Regigigas, leve Regirock, Regice e Registeel na equipe. Você pode trazê-los de outro jogo por transferência ou troca.", "Atravesse os andares do templo com os três na equipe até encontrar Regigigas.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Dialga e Palkia": ["Depois de se tornar Champion, converse com a avó de Cynthia em Celestic Town e volte ao Mt. Coronet.", "Explore a montanha usando Waterfall até encontrar a Adamant Orb e a Lustrous Orb, depois suba novamente até a Spear Pillar.", "Aproxime-se da fenda para encontrar Dialga. Depois da batalha, saia e volte à Spear Pillar para encontrar Palkia.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Articuno, Zapdos e Moltres": ["Depois de receber a National Pokédex, encontre o Professor Carvalho no Pal Park, na Route 221, e depois converse com ele em sua casa em Eterna City.", "Articuno, Zapdos e Moltres começarão a percorrer as rotas de Sinnoh. Use o Marking Map do Pokétch para acompanhar suas localizações e prepare sua equipe para impedir que fujam.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "National Pokédex": ["Depois de se tornar Champion, registre como vistos todos os Pokémon da Pokédex de Sinnoh e volte ao laboratório do Professor Rowan em Sandgem Town.", "Converse com ele para receber a visita do Professor Carvalho, que atualizará sua Pokédex para a National Pokédex."], "Fight Area": ["Vá até o porto de Snowpoint City e embarque no navio para chegar à Fight Area.", "Encontre seu rival e explore a área. Com a National Pokédex, os caminhos para outras partes da ilha estarão disponíveis."], "Survival Area": ["Saia da Fight Area e siga pelas rotas da ilha até chegar à Survival Area.", "Durante a exploração, você encontrará Buck e poderá continuar em direção à Stark Mountain."], "Stark Mountain": ["Siga para a Stark Mountain e atravesse a caverna até encontrar Buck. Continue com ele pelas salas da montanha até chegar à Magma Stone.", "Depois dos acontecimentos na montanha, volte à Survival Area e converse com Buck. Mais tarde, você poderá retornar à montanha para encontrar Heatran."], "Resort Area": ["Continue pelas rotas da ilha até chegar à Resort Area. Explore a Villa e decore a casa com móveis para receber visitas de personagens que encontrou durante a jornada."], "Battle Frontier": ["Na Fight Area, visite a Battle Frontier e escolha entre as instalações disponíveis.", "Cada uma possui regras próprias. Vença as sequências de batalhas para desafiar os Frontier Brains e conquistar seus símbolos de prata e ouro."]}'::jsonb,'{"Uxie": "lendarios", "Azelf": "lendarios", "Mesprit": "lendarios", "Giratina": "lendarios", "Cresselia": "lendarios", "Heatran": "lendarios", "Regigigas": "lendarios", "Dialga e Palkia": "lendarios", "Articuno, Zapdos e Moltres": "lendarios", "National Pokédex": "pos-game", "Fight Area": "pos-game", "Survival Area": "pos-game", "Stark Mountain": "pos-game", "Resort Area": "pos-game", "Battle Frontier": "pos-game"}'::jsonb),
('pokemon-brilliant-diamond',ARRAY['Uxie','Azelf','Mesprit','Giratina','Cresselia','Heatran','Regirock, Regice e Registeel','Regigigas','Raikou, Entei e Suicune','Latios e Latias','Ho-Oh','Kyogre','Groudon','Rayquaza','Mewtwo','Arceus','National Pokédex','Fight Area','Survival Area','Stark Mountain','Resort Area','Battle Tower','Revanche da Liga'],'{"Uxie": ["Depois dos acontecimentos na Spear Pillar, volte para Snowpoint City e siga para oeste até o Lake Acuity.", "Use Surf para chegar à ilha no centro do lago, entre na Acuity Cavern e encontre Uxie.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Azelf": ["Depois dos acontecimentos na Spear Pillar, siga para o Lake Valor, entre Veilstone City e Pastoria City.", "Use Surf para chegar à ilha no centro do lago, entre na Valor Cavern e encontre Azelf.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Mesprit": ["Depois dos acontecimentos na Spear Pillar, volte para Twinleaf Town e siga até o Lake Verity.", "Use Surf para chegar à ilha no centro do lago e entre na Verity Cavern. Ao conversar com Mesprit, ele deixará a caverna e começará a percorrer as rotas de Sinnoh.", "Use o aplicativo Marking Map do Pokétch para acompanhar sua localização e prepare sua equipe para impedir sua fuga.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Giratina": ["Depois de se tornar Champion e receber a National Pokédex, siga pela Route 214 até encontrar o caminho para Sendoff Spring.", "Entre na Turnback Cave e procure as três colunas, depois continue pela próxima passagem para encontrar Giratina.", "Após capturar Giratina e os três Regis do Ramanas Park, você poderá usar a Distortion Slate no parque. Ao vencer a batalha, receberá a Griseous Orb, mas o Giratina dessa sala não pode ser capturado.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Cresselia": ["Depois de se tornar Champion e receber a National Pokédex, vá até a casa do marinheiro em Canalave City e converse com a família dele.", "Fale com o marinheiro no porto para viajar até Fullmoon Island. Encontre Cresselia, pegue a Lunar Feather e entregue-a à família.", "Cresselia começará a percorrer as rotas de Sinnoh. Use o Marking Map do Pokétch para acompanhar sua localização.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Heatran": ["Depois de se tornar Champion e receber a National Pokédex, viaje de Snowpoint City para a Fight Area e siga pelas rotas ao norte até chegar à Stark Mountain.", "Avance pela montanha ao lado de Buck até encontrar a Magma Stone. Depois dos acontecimentos com a Team Galactic, volte à Survival Area e converse com Buck.", "Retorne à sala da Magma Stone para encontrar Heatran.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regirock, Regice e Registeel": ["Depois de se tornar Champion e receber a National Pokédex, siga ao sul de Sandgem Town e atravesse as Routes 219, 220 e 221 para chegar ao Ramanas Park.", "Explore o Grand Underground e procure Mysterious Shards nas escavações. Troque três Mysterious Shards S ou uma Mysterious Shard L por uma Discovery Slate no balcão do parque.", "Use a Slate na Discovery Room para encontrar um dos três Regis. Repita o processo até encontrar Regirock, Regice e Registeel.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regigigas": ["Depois de capturar Regirock, Regice e Registeel no Ramanas Park, coloque os três na equipe e vá ao Snowpoint Temple, ao norte de Snowpoint City.", "Atravesse os andares do templo e encontre Regigigas na parte mais profunda.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Raikou, Entei e Suicune": ["Depois de capturar os três Regis no Ramanas Park, troque Mysterious Shards por uma Johto Slate.", "Use a Slate na Johto Room para encontrar um dos três lendários. Repita o processo até encontrar Raikou, Entei e Suicune.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Latios e Latias": ["Depois de capturar os três Regis no Ramanas Park, troque Mysterious Shards por uma Soul Slate e use-a na Soul Room.", "Repita o processo para encontrar Latios e Latias.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Ho-Oh": ["Depois de capturar Raikou, Entei e Suicune no Ramanas Park, troque Mysterious Shards por uma Rainbow Slate.", "Use a Slate na Rainbow Room para encontrar Ho-Oh.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kyogre": ["Depois de capturar o trio exclusivo da sua versão no Ramanas Park, troque Mysterious Shards por uma Oceanic Slate.", "Use a Slate na Oceanic Room para encontrar Kyogre.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Groudon": ["Depois de capturar o trio exclusivo da sua versão no Ramanas Park, troque Mysterious Shards por uma Tectonic Slate.", "Use a Slate na Tectonic Room para encontrar Groudon.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Rayquaza": ["Depois de capturar o trio exclusivo da sua versão no Ramanas Park, troque Mysterious Shards por uma Stratospheric Slate.", "Use a Slate na Stratospheric Room para encontrar Rayquaza.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Mewtwo": ["Depois de capturar o trio exclusivo da sua versão no Ramanas Park, troque Mysterious Shards por uma Genome Slate.", "Use a Slate na Genome Room para encontrar Mewtwo.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Arceus": ["Para encontrar Arceus, você precisa ter um save de Pokémon Legends: Arceus no mesmo usuário do Nintendo Switch, com todas as missões principais concluídas.", "Em Brilliant Diamond ou Shining Pearl, entre no Hall da Fama, receba a National Pokédex e capture Dialga ou Palkia na Spear Pillar, conforme sua versão.", "Volte ao seu quarto em Twinleaf Town para receber a Azure Flute, depois suba novamente até a Spear Pillar e use a flauta para chegar ao Hall of Origin.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "National Pokédex": ["Depois de se tornar Champion, registre como vistos todos os Pokémon da Pokédex de Sinnoh e volte ao laboratório do Professor Rowan em Sandgem Town.", "Converse com ele para receber a visita do Professor Carvalho, que atualizará sua Pokédex para a National Pokédex."], "Fight Area": ["Vá até o porto de Snowpoint City e embarque no navio para chegar à Fight Area.", "Encontre seu rival e explore a área. Com a National Pokédex, os caminhos para outras partes da ilha estarão disponíveis."], "Survival Area": ["Saia da Fight Area e siga pelas rotas da ilha até chegar à Survival Area.", "Durante a exploração, você encontrará Buck e poderá continuar em direção à Stark Mountain."], "Stark Mountain": ["Siga para a Stark Mountain e atravesse a caverna ao lado de Buck até chegar à Magma Stone.", "Depois dos acontecimentos com a Team Galactic, volte à Survival Area e converse com Buck. Mais tarde, você poderá retornar à montanha para encontrar Heatran."], "Resort Area": ["Continue pelas rotas da ilha até chegar à Resort Area, onde você encontrará uma área de descanso para treinadores."], "Battle Tower": ["Na Fight Area, entre na Battle Tower para enfrentar treinadores em sequências de batalhas.", "Vença os desafios para ganhar Battle Points e trocá-los por itens."], "Revanche da Liga": ["Depois de se tornar Champion, volte à Pokémon League para enfrentar a Elite Four e Cynthia novamente.", "Dessa vez, os treinadores estarão preparados com equipes mais fortes, então treine seus Pokémon e compre itens de recuperação antes de entrar."]}'::jsonb,'{"Uxie": "lendarios", "Azelf": "lendarios", "Mesprit": "lendarios", "Giratina": "lendarios", "Cresselia": "lendarios", "Heatran": "lendarios", "Regirock, Regice e Registeel": "lendarios", "Regigigas": "lendarios", "Raikou, Entei e Suicune": "lendarios", "Latios e Latias": "len