INSERT INTO public.game (slug, caps, dicas, categorias)
SELECT pokemon.slug, guia.caps, guia.dicas, guia.categorias
FROM public.pokemon AS pokemon JOIN guias_sinnoh AS guia ON guia.slug = pokemon.slug
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas, categorias = EXCLUDED.categorias
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

-- Pós-game de Black e White. Somente preenche registros ainda vazios.
WITH guias_unova (slug, caps, dicas, categorias) AS (
VALUES
('pokemon-black',ARRAY['Cobalion','Terrakion','Virizion','Tornadus','Landorus','Kyurem','National Pokédex','Os Sábios da Team Plasma','Volcarona','Leste de Unova','Cynthia','Black City','Champion Alder'],'{"Cobalion": ["Siga para a Route 6 e use Surf no rio até encontrar a entrada da Mistralton Cave.", "Dentro da caverna, use Flash para iluminar o caminho e Strength para mover as pedras. Continue subindo até chegar à Guidance Chamber, onde encontrará Cobalion.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Terrakion": ["Depois de encontrar Cobalion, volte para a Victory Road e explore a caverna próxima à saída para a Pokémon League.", "Procure a entrada da Trial Chamber e entre para encontrar Terrakion.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Virizion": ["Depois de encontrar Cobalion, siga para Nacrene City e entre na Pinwheel Forest.", "Atravesse a floresta até encontrar uma passagem entre as árvores que leva ao Rumination Field. Entre na área para encontrar Virizion.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tornadus": ["Depois de conquistar a oitava insígnia, siga para a Route 7 e aproxime-se da casa perto da passagem para Twist Mountain.", "Uma senhora convidará você a entrar para se proteger da tempestade. Ao sair da casa, você encontrará Tornadus, que começará a percorrer as rotas de Unova.", "Procure notícias sobre tempestades nos painéis das passagens entre cidades e rotas. Tornadus pode fugir da batalha, então prepare sua equipe para impedir sua fuga.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Landorus": ["Para encontrar Landorus, você precisa ter Tornadus e Thundurus na equipe. Como cada versão possui apenas um deles, será necessário conseguir o outro por troca.", "Com os dois na equipe, siga para a Route 14 e use Surf e Waterfall para chegar ao Abundant Shrine.", "Atravesse a área até encontrar o pequeno santuário e interaja com ele para encontrar Landorus.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kyurem": ["Depois dos acontecimentos no N''s Castle, siga para Lacunosa Town e procure a entrada do Giant Chasm na Route 13.", "Atravesse a primeira caverna até chegar a uma floresta, depois siga até o lago no centro da área. A floresta será coberta de neve, abrindo caminho para uma caverna ao norte.", "Entre na caverna para encontrar Kyurem.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "National Pokédex": ["Depois dos acontecimentos no N''s Castle, você voltará para sua casa em Nuvema Town.", "Ao sair de casa, encontre Bianca, Cheren e Cedric Juniper. Ele atualizará sua Pokédex para a National Pokédex, permitindo registrar Pokémon de outras regiões."], "Os Sábios da Team Plasma": ["Ao voltar para casa depois dos acontecimentos no N''s Castle, você conhecerá Looker. Ele pedirá sua ajuda para encontrar os seis sábios da Team Plasma que ainda estão espalhados por Unova.", "Comece pela Route 18 e procure Rood na praia da ilha. Depois, volte ao Dreamyard, perto de Striaton City, e atravesse a área subterrânea para encontrar Gorm.", "Em Driftveil City, entre novamente no Cold Storage e procure Zinzolin no contêiner onde você enfrentou a Team Plasma durante a campanha.", "Volte à Chargestone Cave e desça até os andares inferiores para encontrar Bronius. Prepare sua equipe, pois dois membros da Team Plasma desafiarão você.", "No Relic Castle, atravesse os andares inferiores e siga pela passagem aberta no fundo para encontrar Ryoku.", "Por último, siga para a Route 14 e use Surf e Waterfall para alcançar Giallo acima da cachoeira. Depois de encontrar os seis, Looker contará sobre uma notícia envolvendo N."], "Volcarona": ["Durante a busca por Ryoku, continue explorando a parte mais profunda do Relic Castle até encontrar a sala de Volcarona.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Leste de Unova": ["Depois de receber a National Pokédex, volte para Opelucid City e siga para leste pela Route 11.", "Atravesse a Village Bridge e continue pela Route 12 até Lacunosa Town. De lá, siga pela Route 13 para chegar a Undella Town.", "Os treinadores dessa parte de Unova possuem equipes mais fortes, então aproveite o caminho para treinar seus Pokémon antes dos próximos desafios."], "Cynthia": ["Em Undella Town, entre na casa onde Cynthia está hospedada e converse com ela para iniciar uma batalha.", "Cynthia possui uma equipe forte, então prepare seus Pokémon e seus itens antes de enfrentá-la."], "Black City": ["Continue ao sul de Undella Town pela Route 14 até chegar a Black City.", "Explore a cidade e enfrente os treinadores disponíveis para continuar fortalecendo sua equipe."], "Champion Alder": ["Depois dos acontecimentos no N''s Castle, volte à Pokémon League e enfrente a Elite Four novamente.", "Dessa vez, após vencer os quatro treinadores, você terá acesso à sala do Champion e poderá enfrentar Alder para concluir o desafio da Liga.", "Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas."]}'::jsonb,'{"Cobalion": "lendarios", "Terrakion": "lendarios", "Virizion": "lendarios", "Tornadus": "lendarios", "Landorus": "lendarios", "Kyurem": "lendarios", "National Pokédex": "pos-game", "Os Sábios da Team Plasma": "pos-game", "Volcarona": "pos-game", "Leste de Unova": "pos-game", "Cynthia": "pos-game", "Black City": "pos-game", "Champion Alder": "pos-game"}'::jsonb),
('pokemon-white',ARRAY['Cobalion','Terrakion','Virizion','Thundurus','Landorus','Kyurem','National Pokédex','Os Sábios da Team Plasma','Volcarona','Leste de Unova','Cynthia','White Forest','Champion Alder'],'{"Cobalion": ["Siga para a Route 6 e use Surf no rio até encontrar a entrada da Mistralton Cave.", "Dentro da caverna, use Flash para iluminar o caminho e Strength para mover as pedras. Continue subindo até chegar à Guidance Chamber, onde encontrará Cobalion.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Terrakion": ["Depois de encontrar Cobalion, volte para a Victory Road e explore a caverna próxima à saída para a Pokémon League.", "Procure a entrada da Trial Chamber e entre para encontrar Terrakion.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Virizion": ["Depois de encontrar Cobalion, siga para Nacrene City e entre na Pinwheel Forest.", "Atravesse a floresta até encontrar uma passagem entre as árvores que leva ao Rumination Field. Entre na área para encontrar Virizion.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Thundurus": ["Depois de conquistar a oitava insígnia, siga para a Route 7 e aproxime-se da casa perto da passagem para Twist Mountain.", "Uma senhora convidará você a entrar para se proteger da tempestade. Ao sair da casa, você encontrará Thundurus, que começará a percorrer as rotas de Unova.", "Procure notícias sobre tempestades nos painéis das passagens entre cidades e rotas. Thundurus pode fugir da batalha, então prepare sua equipe para impedir sua fuga.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Landorus": ["Para encontrar Landorus, você precisa ter Tornadus e Thundurus na equipe. Como cada versão possui apenas um deles, será necessário conseguir o outro por troca.", "Com os dois na equipe, siga para a Route 14 e use Surf e Waterfall para chegar ao Abundant Shrine.", "Atravesse a área até encontrar o pequeno santuário e interaja com ele para encontrar Landorus.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kyurem": ["Depois dos acontecimentos no N''s Castle, siga para Lacunosa Town e procure a entrada do Giant Chasm na Route 13.", "Atravesse a primeira caverna até chegar a uma floresta, depois siga até o lago no centro da área. A floresta será coberta de neve, abrindo caminho para uma caverna ao norte.", "Entre na caverna para encontrar Kyurem.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "National Pokédex": ["Depois dos acontecimentos no N''s Castle, você voltará para sua casa em Nuvema Town.", "Ao sair de casa, encontre Bianca, Cheren e Cedric Juniper. Ele atualizará sua Pokédex para a National Pokédex, permitindo registrar Pokémon de outras regiões."], "Os Sábios da Team Plasma": ["Ao voltar para casa depois dos acontecimentos no N''s Castle, você conhecerá Looker. Ele pedirá sua ajuda para encontrar os seis sábios da Team Plasma que ainda estão espalhados por Unova.", "Comece pela Route 18 e procure Rood na praia da ilha. Depois, volte ao Dreamyard, perto de Striaton City, e atravesse a área subterrânea para encontrar Gorm.", "Em Driftveil City, entre novamente no Cold Storage e procure Zinzolin no contêiner onde você enfrentou a Team Plasma durante a campanha.", "Volte à Chargestone Cave e desça até os andares inferiores para encontrar Bronius. Prepare sua equipe, pois dois membros da Team Plasma desafiarão você.", "No Relic Castle, atravesse os andares inferiores e siga pela passagem aberta no fundo para encontrar Ryoku.", "Por último, siga para a Route 14 e use Surf e Waterfall para alcançar Giallo acima da cachoeira. Depois de encontrar os seis, Looker contará sobre uma notícia envolvendo N."], "Volcarona": ["Durante a busca por Ryoku, continue explorando a parte mais profunda do Relic Castle até encontrar a sala de Volcarona.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Leste de Unova": ["Depois de receber a National Pokédex, volte para Opelucid City e siga para leste pela Route 11.", "Atravesse a Village Bridge e continue pela Route 12 até Lacunosa Town. De lá, siga pela Route 13 para chegar a Undella Town.", "Os treinadores dessa parte de Unova possuem equipes mais fortes, então aproveite o caminho para treinar seus Pokémon antes dos próximos desafios."], "Cynthia": ["Em Undella Town, entre na casa onde Cynthia está hospedada e converse com ela para iniciar uma batalha.", "Cynthia possui uma equipe forte, então prepare seus Pokémon e seus itens antes de enfrentá-la."], "White Forest": ["Continue ao sul de Undella Town pela Route 14 até chegar a White Forest.", "Explore a floresta para encontrar Pokémon de outras regiões e continuar preenchendo sua National Pokédex."], "Champion Alder": ["Depois dos acontecimentos no N''s Castle, volte à Pokémon League e enfrente a Elite Four novamente.", "Dessa vez, após vencer os quatro treinadores, você terá acesso à sala do Champion e poderá enfrentar Alder para concluir o desafio da Liga.", "Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas."]}'::jsonb,'{"Cobalion": "lendarios", "Terrakion": "lendarios", "Virizion": "lendarios", "Thundurus": "lendarios", "Landorus": "lendarios", "Kyurem": "lendarios", "National Pokédex": "pos-game", "Os Sábios da Team Plasma": "pos-game", "Volcarona": "pos-game", "Leste de Unova": "pos-game", "Cynthia": "pos-game", "White Forest": "pos-game", "Champion Alder": "pos-game"}'::jsonb)
)
INSERT INTO public.game (slug, caps, dicas, categorias)
SELECT pokemon.slug, guia.caps, guia.dicas, guia.categorias
FROM public.pokemon AS pokemon JOIN guias_unova AS guia ON guia.slug = pokemon.slug
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas, categorias = EXCLUDED.categorias
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

-- Pós-game de Black 2 e White 2. Somente preenche registros ainda vazios.
WITH guias_unova2 (slug, caps, dicas, categorias) AS (
VALUES
('pokemon-black-2',ARRAY['Cobalion','Terrakion','Virizion','Zekrom','Kyurem','Regirock','Registeel','Regice','Regigigas','Latios','Heatran','Cresselia','Uxie, Mesprit e Azelf','National Pokédex','N''s Castle','Alder','Black Tower','Haxorus shiny','Pokémon World Tournament','Revanche da Liga'],'{"Cobalion": ["Durante a jornada, Cobalion pode ser encontrado na Route 13. Volte à rota e procure-o no caminho entre Undella Town e Lacunosa Town.", "Se você o derrotou durante a campanha sem capturá-lo, volte depois de vencer a Liga para encontrá-lo novamente.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Terrakion": ["Siga para a Route 22, a oeste de Humilau City, e procure Terrakion no caminho.", "Se você o derrotou durante a campanha sem capturá-lo, volte depois de vencer a Liga para encontrá-lo novamente.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Virizion": ["Siga para a Route 11, entre Opelucid City e a Village Bridge, e procure Virizion no caminho.", "Se você o derrotou durante a campanha sem capturá-lo, volte depois de vencer a Liga para encontrá-lo novamente.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Zekrom": ["Depois de se tornar Champion, volte à Victory Road pela entrada próxima da Pokémon League.", "Procure Zoroark dentro da caverna e siga-o até as ruínas do N''s Castle. Entre no castelo e avance até encontrar N, que desafiará você para uma batalha com Zekrom.", "Depois de vencê-lo, receba a Dark Stone e siga para a Dragonspiral Tower, ao norte de Icirrus City. Suba até o último andar para despertar Zekrom.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kyurem": ["Depois de capturar Zekrom em Black 2 ou Reshiram em White 2, volte para o Giant Chasm.", "Atravesse a área até chegar à caverna onde aconteceram os eventos da Team Plasma durante a campanha. Lá, você encontrará Kyurem.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Após a batalha, pegue o DNA Splicers para unir Kyurem a Zekrom ou Reshiram e obter Black Kyurem ou White Kyurem."], "Regirock": ["Depois de se tornar Champion, siga para Driftveil City e entre no Clay Tunnel. Atravesse o túnel até encontrar as Underground Ruins.", "Na sala com os círculos no chão, fique no centro, dê nove passos para a direita e seis para baixo, depois examine o chão para encontrar um interruptor escondido.", "A passagem se abrirá e você poderá entrar na sala de Regirock.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Registeel": ["Depois de capturar Regirock, você receberá a Iron Key em Black 2. Para usá-la em White 2, será necessário recebê-la de outro jogador pelo Unova Link.", "Salve o jogo e volte ao menu inicial. Entre no Unova Link, selecione Key System e use a Iron Key para mudar a sala das Underground Ruins.", "Carregue o jogo e volte à sala onde encontrou Regirock para encontrar Registeel.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regice": ["Depois de capturar Regirock, você receberá a Iceberg Key em White 2. Para usá-la em Black 2, será necessário recebê-la de outro jogador pelo Unova Link.", "Salve o jogo e volte ao menu inicial. Entre no Unova Link, selecione Key System e use a Iceberg Key para mudar a sala das Underground Ruins.", "Carregue o jogo e volte à sala onde encontrou Regirock para encontrar Regice.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regigigas": ["Coloque Regirock, Regice e Registeel na equipe e siga para Twist Mountain.", "Explore os andares da montanha até encontrar uma sala com três estátuas e Regigigas. Caso não tenha uma das chaves da outra versão, você também pode conseguir o Regi que falta por troca.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Latios": ["Depois de se tornar Champion, volte para Striaton City e entre no Dreamyard.", "Latios aparecerá e voará pela área. Continue seguindo-o pelas ruínas até ele parar e iniciar a batalha.", "Salve antes de se aproximar do ponto onde ele pousar e prepare suas Poké Balls antes de enfrentá-lo."], "Heatran": ["Siga até a Route 18 e explore a ilha para encontrar a Magma Stone.", "Com ela na bolsa, volte para Reversal Mountain e procure a sala onde Bianca comentou sobre a presença de um Pokémon. Entre na área para encontrar Heatran.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Cresselia": ["Entre na Strange House, perto de Lentimas Town, e explore seus andares até encontrar a Lunar Wing.", "Com a Lunar Wing na bolsa, siga para a Marvelous Bridge e avance até encontrar Cresselia.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Uxie, Mesprit e Azelf": ["Depois de se tornar Champion, siga para a Route 20 e use Waterfall para chegar à Cave of Being.", "Entre na caverna e encontre a Professora Juniper. Depois da aparição, Uxie, Mesprit e Azelf partirão para locais diferentes de Unova.", "Para encontrar Uxie, vá até a entrada do museu em Nacrene City.", "Para encontrar Mesprit, suba até o topo da Celestial Tower.", "Para encontrar Azelf, explore a parte oeste da Route 23, perto das pedras que podem ser movidas com Strength.", "Ao chegar a cada lugar, caminhe pela área indicada para perceber a presença do Pokémon e iniciar o encontro.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "National Pokédex": ["Depois de se tornar Champion, volte para casa em Aspertia City. Cedric Juniper visitará você e atualizará sua Pokédex para a National Pokédex.", "Com ela, você poderá registrar Pokémon de outras regiões e continuar explorando Unova."], "N''s Castle": ["Volte à Victory Road pela entrada próxima da Pokémon League e procure Zoroark dentro da caverna.", "Siga-o até as ruínas do N''s Castle e explore o castelo até chegar à sala de N. Enfrente-o para continuar a jornada até Zekrom ou Reshiram, conforme sua versão."], "Alder": ["Vá até Floccesy Town e visite a casa de Alder. Prepare sua equipe e converse com o antigo Champion para enfrentá-lo.", "Depois da batalha, você conhecerá Benga, neto de Alder, que contará sobre um novo desafio em Black City ou White Forest."], "Black Tower": ["Depois de enfrentar Alder, siga para Black City e entre na Black Tower.", "Atravesse as áreas enfrentando treinadores até chegar ao último desafio, onde Benga estará esperando.", "Depois de vencê-lo, volte à casa de Alder em Floccesy Town e converse com Benga para receber um Gible shiny."], "Haxorus shiny": ["Registre como vistos os Pokémon de número 001 a 297 da Pokédex de Unova. Você não precisa capturá-los e também não precisa registrar os Pokémon exclusivos de eventos.", "Depois, visite a Professora Juniper em Nuvema Town para receber o Permit.", "Vá ao aeroporto de Mistralton City e use a permissão para viajar à Nature Preserve. Explore a área até encontrar um Haxorus shiny, que já aparece nessa forma.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Pokémon World Tournament": ["Volte ao Pokémon World Tournament, ao sul de Driftveil City, para participar de novos torneios.", "Continue vencendo os desafios para liberar competições contra líderes de ginásio e Champions de outras regiões."], "Revanche da Liga": ["Volte à Pokémon League e enfrente a Elite Four e Iris novamente. Dessa vez, os treinadores estarão preparados com equipes mais fortes.", "Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas."]}'::jsonb,'{"Cobalion": "lendarios", "Terrakion": "lendarios", "Virizion": "lendarios", "Zekrom": "lendarios", "Kyurem": "lendarios", "Regirock": "lendarios", "Registeel": "lendarios", "Regice": "lendarios", "Regigigas": "lendarios", "Latios": "lendarios", "Heatran": "lendarios", "Cresselia": "lendarios", "Uxie, Mesprit e Azelf": "lendarios", "National Pokédex":