INSERT INTO public.game (slug, caps, dicas, categorias)
SELECT pokemon.slug, guia.caps, guia.dicas, guia.categorias
FROM public.pokemon AS pokemon JOIN guias_unova2 AS guia ON guia.slug = pokemon.slug
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas, categorias = EXCLUDED.categorias
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

-- Pós-game de X, Y, Sun e Moon. Somente preenche registros ainda vazios.
WITH guias_kalos_alola (slug, caps, dicas, categorias) AS (
VALUES
('pokemon-x',ARRAY['Zygarde','Mewtwo','Articuno, Zapdos ou Moltres','Kiloude City','Battle Maison','Rival','Mega Ring','Looker Bureau','Emma e Mimi','Essentia','Revanche da Liga'],'{"Zygarde": ["Depois de se tornar Champion, siga para a Route 18 e entre na Terminus Cave.", "Atravesse os andares da caverna e continue até a sala mais profunda, onde encontrará Zygarde em sua forma de 50%.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Mewtwo": ["Depois de se tornar Champion, volte para Pokémon Village pela Route 20.", "Use Surf no rio para chegar à entrada da caverna que antes estava bloqueada. Entre na Unknown Dungeon e encontre Mewtwo.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Após capturá-lo, pegue a Mewtwonite X que aparecerá no chão."], "Articuno, Zapdos ou Moltres": ["Depois de se tornar Champion, uma das três aves lendárias começará a percorrer as rotas de Kalos. O Pokémon depende do inicial escolhido no começo da jornada.", "Se você escolheu Chespin, encontrará Articuno. Se escolheu Fennekin, encontrará Zapdos. Se escolheu Froakie, encontrará Moltres.", "Procure o lendário na grama e consulte sua localização na Pokédex. Ele fugirá assim que aparecer, então continue procurando até ele parar de percorrer as rotas.", "Depois de encontrá-lo 11 vezes, contando o primeiro encontro, siga para Azure Bay e use Surf até a Sea Spirit’s Den. Entre na caverna para encontrar o lendário.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kiloude City": ["Depois de se tornar Champion, vá até a Lumiose Station em Lumiose City. Ao entrar na estação, Dexio atualizará sua Pokédex para a National Pokédex.", "Encontre o Professor Sycamore e receba o TMV Pass, depois use o trem para viajar até Kiloude City."], "Battle Maison": ["Em Kiloude City, entre na Battle Maison e participe de uma batalha.", "Depois, explore os desafios disponíveis e enfrente treinadores em sequências de batalhas para ganhar Battle Points, que podem ser trocados por itens."], "Rival": ["Depois de participar de uma batalha na Battle Maison, siga para a parte norte de Kiloude City e encontre seu rival perto do lago.", "Enfrente-o novamente e, após a vitória, receba a Absolite. Seu rival também contará que o Professor Sycamore está esperando em Anistar City."], "Mega Ring": ["Vá para Anistar City e encontre o Professor Sycamore perto do relógio de sol.", "Converse com ele e toque no cristal para fortalecer seu Mega Ring. Depois disso, você poderá encontrar algumas Mega Stones escondidas por Kalos entre 20h e 21h, de acordo com o relógio do seu console."], "Looker Bureau": ["Depois de fortalecer o Mega Ring, volte para Lumiose City. Você receberá uma mensagem no Holo Caster convidando-o a conhecer o Looker Bureau.", "Entre no escritório e converse com Looker, que pedirá sua ajuda para encontrar cinco Looker Tickets espalhados pela cidade.", "Procure os tickets no Pokémon Center perto da Magenta Plaza, na Prism Tower, na loja Herboriste, no Hotel Richissime e no Lumiose Museum. Depois de encontrar todos, volte ao escritório."], "Emma e Mimi": ["Continue ajudando Looker nas investigações de Lumiose City. Durante os casos, você conhecerá Emma e seu Espurr, Mimi.", "Converse com os personagens, explore os becos da cidade e volte ao escritório quando Looker chamar você para continuar as investigações."], "Essentia": ["Ao continuar os casos do Looker Bureau, procure informações sobre uma figura misteriosa chamada Essentia.", "Siga as pistas por Lumiose City e enfrente os desafios da investigação até descobrir a ligação de Essentia com Emma e Xerosic.", "Continue até os acontecimentos no Lysandre Café e volte ao escritório para concluir a história de Looker e Emma."], "Revanche da Liga": ["Volte à Pokémon League para enfrentar a Elite Four e Diantha novamente.", "Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas."]}'::jsonb,'{"Zygarde": "lendarios", "Mewtwo": "lendarios", "Articuno, Zapdos ou Moltres": "lendarios", "Kiloude City": "pos-game", "Battle Maison": "pos-game", "Rival": "pos-game", "Mega Ring": "pos-game", "Looker Bureau": "pos-game", "Emma e Mimi": "pos-game", "Essentia": "pos-game", "Revanche da Liga": "pos-game"}'::jsonb),
('pokemon-y',ARRAY['Zygarde','Mewtwo','Articuno, Zapdos ou Moltres','Kiloude City','Battle Maison','Rival','Mega Ring','Looker Bureau','Emma e Mimi','Essentia','Revanche da Liga'],'{"Zygarde": ["Depois de se tornar Champion, siga para a Route 18 e entre na Terminus Cave.", "Atravesse os andares da caverna e continue até a sala mais profunda, onde encontrará Zygarde em sua forma de 50%.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Mewtwo": ["Depois de se tornar Champion, volte para Pokémon Village pela Route 20.", "Use Surf no rio para chegar à entrada da caverna que antes estava bloqueada. Entre na Unknown Dungeon e encontre Mewtwo.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Após capturá-lo, pegue a Mewtwonite Y que aparecerá no chão."], "Articuno, Zapdos ou Moltres": ["Depois de se tornar Champion, uma das três aves lendárias começará a percorrer as rotas de Kalos. O Pokémon depende do inicial escolhido no começo da jornada.", "Se você escolheu Chespin, encontrará Articuno. Se escolheu Fennekin, encontrará Zapdos. Se escolheu Froakie, encontrará Moltres.", "Procure o lendário na grama e consulte sua localização na Pokédex. Ele fugirá assim que aparecer, então continue procurando até ele parar de percorrer as rotas.", "Depois de encontrá-lo 11 vezes, contando o primeiro encontro, siga para Azure Bay e use Surf até a Sea Spirit’s Den. Entre na caverna para encontrar o lendário.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kiloude City": ["Depois de se tornar Champion, vá até a Lumiose Station em Lumiose City. Ao entrar na estação, Dexio atualizará sua Pokédex para a National Pokédex.", "Encontre o Professor Sycamore e receba o TMV Pass, depois use o trem para viajar até Kiloude City."], "Battle Maison": ["Em Kiloude City, entre na Battle Maison e participe de uma batalha.", "Depois, explore os desafios disponíveis e enfrente treinadores em sequências de batalhas para ganhar Battle Points, que podem ser trocados por itens."], "Rival": ["Depois de participar de uma batalha na Battle Maison, siga para a parte norte de Kiloude City e encontre seu rival perto do lago.", "Enfrente-o novamente e, após a vitória, receba a Absolite. Seu rival também contará que o Professor Sycamore está esperando em Anistar City."], "Mega Ring": ["Vá para Anistar City e encontre o Professor Sycamore perto do relógio de sol.", "Converse com ele e toque no cristal para fortalecer seu Mega Ring. Depois disso, você poderá encontrar algumas Mega Stones escondidas por Kalos entre 20h e 21h, de acordo com o relógio do seu console."], "Looker Bureau": ["Depois de fortalecer o Mega Ring, volte para Lumiose City. Você receberá uma mensagem no Holo Caster convidando-o a conhecer o Looker Bureau.", "Entre no escritório e converse com Looker, que pedirá sua ajuda para encontrar cinco Looker Tickets espalhados pela cidade.", "Procure os tickets no Pokémon Center perto da Magenta Plaza, na Prism Tower, na loja Herboriste, no Hotel Richissime e no Lumiose Museum. Depois de encontrar todos, volte ao escritório."], "Emma e Mimi": ["Continue ajudando Looker nas investigações de Lumiose City. Durante os casos, você conhecerá Emma e seu Espurr, Mimi.", "Converse com os personagens, explore os becos da cidade e volte ao escritório quando Looker chamar você para continuar as investigações."], "Essentia": ["Ao continuar os casos do Looker Bureau, procure informações sobre uma figura misteriosa chamada Essentia.", "Siga as pistas por Lumiose City e enfrente os desafios da investigação até descobrir a ligação de Essentia com Emma e Xerosic.", "Continue até os acontecimentos no Lysandre Café e volte ao escritório para concluir a história de Looker e Emma."], "Revanche da Liga": ["Volte à Pokémon League para enfrentar a Elite Four e Diantha novamente.", "Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas."]}'::jsonb,'{"Zygarde": "lendarios", "Mewtwo": "lendarios", "Articuno, Zapdos ou Moltres": "lendarios", "Kiloude City": "pos-game", "Battle Maison": "pos-game", "Rival": "pos-game", "Mega Ring": "pos-game", "Looker Bureau": "pos-game", "Emma e Mimi": "pos-game", "Essentia": "pos-game", "Revanche da Liga": "pos-game"}'::jsonb),
('pokemon-sun',ARRAY['Tapu Koko','Tapu Lele','Tapu Bulu','Tapu Fini','Cosmog','Zygarde','Necrozma','Nihilego','Buzzwole','Xurkitree','Kartana','Guzzlord','Looker e Anabel','Type: Null','Battle Tree','Defesa do título'],'{"Tapu Koko": ["Depois de se tornar Champion, volte para as Ruins of Conflict, na ilha de Melemele.", "Aproxime-se da estátua dentro das ruínas para encontrar Tapu Koko, o guardião da ilha.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Lele": ["Depois de se tornar Champion, siga para Akala Outskirts e entre nas Ruins of Life.", "Atravesse as ruínas até chegar à estátua e interaja com ela para encontrar Tapu Lele.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Bulu": ["Depois de se tornar Champion, siga para o Haina Desert, ao norte da Route 13, na ilha de Ula’ula.", "Atravesse o deserto até encontrar as Ruins of Abundance. Entre e aproxime-se da estátua para encontrar Tapu Bulu.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Fini": ["Depois de se tornar Champion, volte para Poni Breaker Coast e siga até as Ruins of Hope.", "Atravesse as ruínas e interaja com a estátua para encontrar Tapu Fini.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Cosmog": ["Depois de se tornar Champion, coloque Solgaleo na equipe e volte ao Altar of the Sunne durante a noite.", "Atravesse o portal e siga para o Lake of the Sunne. Entre no altar do lago e avance até receber Cosmog."], "Zygarde": ["Durante a jornada por Alola, procure as células e os núcleos de Zygarde espalhados pelas ilhas e guarde-os no Zygarde Cube.", "Com células suficientes, visite o laboratório na Route 16, em Ula’ula, e use a máquina para formar Zygarde. Continue procurando as células para desbloquear suas formas e habilidades."], "Necrozma": ["Depois de concluir as missões de captura das Ultra Beasts com Looker e Anabel, volte à Aether Paradise para conversar com eles.", "Após ouvir o relato de Looker sobre um Pokémon misterioso, siga para Ten Carat Hill, em Melemele, e procure na grama da área mais profunda até encontrar Necrozma.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Nihilego": ["Depois de se tornar Champion, você receberá um cartão misterioso. Siga para o motel da Route 8, em Akala, e converse com Looker e Anabel para começar a investigação das Ultra Beasts.", "Depois da batalha com Anabel, visite a Aether Paradise e converse com Wicke para receber Beast Balls. Volte ao motel para receber sua primeira missão.", "Procure Nihilego na grama do Wela Volcano Park ou dentro do Diglett’s Tunnel.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Depois de capturá-lo, volte ao motel e informe Looker."], "Buzzwole": ["Depois de concluir a missão de Nihilego, encontre Looker e Anabel no motel da Route 2, em Melemele.", "Siga para Melemele Meadow e procure Buzzwole na grama.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Capture os dois Buzzwole encontrados na área e volte ao motel para informar Looker."], "Xurkitree": ["Depois de concluir a missão de Buzzwole, volte a falar com Looker e Anabel para receber a próxima missão.", "Siga para Lush Jungle ou Memorial Hill, em Akala, e procure Xurkitree.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Capture os dois encontrados e volte para informar Looker."], "Kartana": ["Depois de concluir a missão de Xurkitree, encontre Looker e Anabel no motel da Route 13, em Ula’ula.", "Siga para a Route 17 ou para Malie Garden e procure Kartana.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Capture os quatro encontrados e volte ao motel para informar Looker."], "Guzzlord": ["Depois de concluir a missão de Kartana, volte a falar com Looker e Anabel para receber a última missão.", "Siga para Poni Island e explore a Resolution Cave até encontrar Guzzlord na parte mais profunda.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Depois de capturá-lo, volte para informar Looker e conclua a investigação na Aether Paradise."], "Looker e Anabel": ["Depois de se tornar Champion, você receberá um cartão misterioso com instruções para visitar o motel da Route 8.", "Lá, encontre Looker e Anabel para descobrir que Ultra Beasts apareceram em Alola. Aceite ajudá-los e siga as missões de captura por cada ilha.", "Use as Beast Balls recebidas durante a investigação e volte a falar com Looker depois de concluir cada missão."], "Type: Null": ["Depois de se tornar Champion, volte para a Aether Paradise e procure Gladion na área de conservação.", "Converse com ele para receber um Type: Null. Gladion também entregará itens que permitem mudar o tipo de Silvally quando Type: Null evoluir."], "Battle Tree": ["Depois de se tornar Champion, siga para Poni Island e explore os caminhos além de Poni Grove até chegar à Battle Tree.", "Na entrada, você encontrará Red e Blue. Escolha um dos dois para enfrentar antes de entrar.", "Dentro da Battle Tree, participe de sequências de batalhas para ganhar Battle Points e trocá-los por itens."], "Defesa do título": ["Volte à Pokémon League para enfrentar a Elite Four novamente.", "Depois de vencer os quatro treinadores, sente-se no lugar de Champion e receba um desafiante para defender seu título.", "Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas."]}'::jsonb,'{"Tapu Koko": "lendarios", "Tapu Lele": "lendarios", "Tapu Bulu": "lendarios", "Tapu Fini": "lendarios", "Cosmog": "lendarios", "Zygarde": "lendarios", "Necrozma": "lendarios", "Nihilego": "lendarios", "Buzzwole": "lendarios", "Xurkitree": "lendarios", "Kartana": "lendarios", "Guzzlord": "lendarios", "Looker e Anabel": "pos-game", "Type: Null": "pos-game", "Battle Tree": "pos-game", "Defesa do título": "pos-game"}'::jsonb),
('pokemon-moon',ARRAY['Tapu Koko','Tapu Lele','Tapu Bulu','Tapu Fini','Cosmog','Zygarde','Necrozma','Nihilego','Pheromosa','Xurkitree','Celesteela','Guzzlord','Looker e Anabel','Type: Null','Battle Tree','Defesa do título'],'{"Tapu Koko": ["Depois de se tornar Champion, volte para as Ruins of Conflict, na ilha de Melemele.", "Aproxime-se da estátua dentro das ruínas para encontrar Tapu Koko, o guardião da ilha.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Lele": ["Depois de se tornar Champion, siga para Akala Outskirts e entre nas Ruins of Life.", "Atravesse as ruínas até chegar à estátua e interaja com ela para encontrar Tapu Lele.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Bulu": ["Depois de se tornar Champion, siga para o Haina Desert, ao norte da Route 13, na ilha de Ula’ula.", "Atravesse o deserto até encontrar as Ruins of Abundance. Entre e aproxime-se da estátua para encontrar Tapu Bulu.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Fini": ["Depois de se tornar Champion, volte para Poni Breaker Coast e siga até as Ruins of Hope.", "Atravesse as ruínas e interaja com a estátua para encontrar Tapu Fini.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Cosmog": ["Depois de se tornar Champion, coloque Lunala na equipe e volte ao Altar of the Moone durante o dia.", "Atravesse o portal e siga para o Lake of the Moone. Entre no altar do lago e avance até receber Cosmog."], "Zygarde": ["Durante a jornada por Alola, procure as células e os núcleos de Zygarde espalhados pelas ilhas e guarde-os no Zygarde Cube.", "Com células suficientes, visite o laboratório na Route 16, em Ula’ula, e use a máquina para formar Zygarde. Continue procurando as células para desbloquear suas formas e habilidades."], "Necrozma": ["Depois de concluir as missões de captura das Ultra Beasts com Looker e Anabel, volte à Aether Paradise para conversar com eles.", "Após ouvir o relato de Looker sobre um Pokémon misterioso, siga para Ten Carat Hill, em Melemele, e procure na grama da área mais profunda até encontrar Necrozma.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Nihilego": ["Depois de se tornar Champion, você receberá um cartão misterioso. Siga para o motel da Route 8, em Akala, e converse com Looker e Anabel para começar a investigação das Ultra Beasts.", "Depois da batalha com Anabel, visite a Aether Paradise e converse com Wicke para receber Beast Balls. Volte ao motel para receber sua primeira missão.", "Procure Nihilego na grama do Wela Volcano Park ou dentro do Diglett’s Tunnel.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Depois de capturá-lo, volte ao motel e informe Looker."], "Pheromosa": ["Depois de concluir a missão de Nihilego, encontre Looker e Anabel no motel da Route 2, em Melemele.", "Siga para Verdant Cavern e procure Pheromosa dentro da caverna.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Capture os quatro Pheromosa encontrados na área e volte ao motel para informar Looker."], "Xurkitree": ["Depois de concluir a missão de Pheromosa, volte a falar com Looker e Anabel para receber a próxima missão.", "Siga para Lush Jungle ou Memorial Hill, em Akala, e procure Xurkitree.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Capture os dois encontrados e volte para informar Looker."], "Celesteela": ["Depois de concluir a missão de Xurkitree, encontre Looker e Anabel no motel da Route 13, em Ula’ula.", "Siga para o Haina Desert ou para Malie Garden e procure Celesteela.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Capture os dois encontrados e volte ao motel para informar Looker."], "Guzzlord": ["Depois de concluir a missão de Celesteela, volte a falar com Looker e Anabel para receber a última missão.", "Siga para Poni Island e explore a Resolution Cave até encontrar Guzzlord na parte mais profunda.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Depois de capturá-lo, volte para informar Looker e conclua a investigação na Aether Paradise."], "Looker e Anabel": ["Depois de se tornar Champion, você receberá um cartão misterioso com instruções para visitar o motel da Route 8.", "Lá, encontre Looker e Anabel para descobrir que Ultra Beasts apareceram em Alola. Aceite ajudá-los e siga as missões de captura por cada ilha.", "Use as Beast Balls recebidas durante a investigação e volte a falar com Looker depois de concluir cada missão."], "Type: Null": ["Depois de se tornar Champion, volte para a Aether Paradise e procure Gladion na área de conservação.", "Converse com ele para receber um Type: Null. Gladion também entregará itens que permitem mudar o tipo de Silvally quando Type: Null evoluir."], "Battle Tree": ["Depois de se tornar Champion, siga para Poni Island e explore os caminhos além de Poni Grove até chegar à Battle Tree.", "Na entrada, você encontrará Red e Blue. Escolha um dos dois para enfrentar antes de entrar.", "Dentro da Battle Tree, participe de sequências de batalhas para ganhar Battle Points e trocá-los por itens."], "Defesa do título": ["Volte à Pokémon League para enfrentar a Elite Four novamente.", "Depois de vencer os quatro treinadores, sente-se no lugar de Champion e receba um desafiante para defender seu título.", "Prepare sua equipe e compre itens de recuperação antes de entrar, pois não será possível voltar ao Pokémon Center entre as batalhas, embora você possa usar itens na equipe entre elas."]}'::jsonb,'{"Tapu Koko": "lendarios", "Tapu Lele": "lendarios", "Tapu Bulu": "lendarios", "Tapu Fini": "lendarios", "Cosmog": "lendarios", "Zygarde": "lendarios", "Necrozma": "lendarios", "Nihilego": "lendarios", "Pheromosa": "lendarios", "Xurkitree": "lendarios", "Celesteela": "lendarios", "Guzzlord": "lendarios", "Looker e Anabel": "pos-game", "Type: Null": "pos-game", "Battle Tree": "pos-game"