INSERT INTO public.game (slug, caps, dicas, categorias)
SELECT pokemon.slug, guia.caps, guia.dicas, guia.categorias
FROM public.pokemon AS pokemon JOIN guias_kalos_alola AS guia ON guia.slug = pokemon.slug
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas, categorias = EXCLUDED.categorias
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

-- Pós-game de Ultra Sun e Ultra Moon. Somente preenche registros ainda vazios.
WITH guias_ultra (slug, caps, dicas, categorias) AS (
VALUES
('pokemon-ultra-sun',ARRAY['Tapu Koko','Tapu Lele','Tapu Bulu','Tapu Fini','Zygarde','Cosmog','Blacephalon','Poipole','Nihilego','Buzzwole','Xurkitree','Kartana','Guzzlord','Articuno, Zapdos e Moltres','Mewtwo','Raikou e Suicune','Ho-Oh','Regirock, Regice e Registeel','Latios','Groudon e Rayquaza','Uxie, Mesprit e Azelf','Dialga e Giratina','Heatran','Cresselia','Cobalion, Terrakion e Virizion','Tornadus e Landorus','Reshiram e Kyurem','Xerneas','Ultra Recon Squad','Episode RR','Type: Null','Battle Tree','Totem Stickers','Defesa do título'],'{"Tapu Koko": ["Depois de se tornar Champion, siga para Ruins of Conflict, na ilha de Melemele.", "Atravesse as ruínas e interaja com a estátua para encontrar Tapu Koko.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Lele": ["Depois de se tornar Champion, siga para Ruins of Life, em Akala Outskirts.", "Atravesse as ruínas e interaja com a estátua para encontrar Tapu Lele.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Bulu": ["Depois de se tornar Champion, siga para Ruins of Abundance, ao norte do Haina Desert, na ilha de Ula’ula.", "Atravesse as ruínas e interaja com a estátua para encontrar Tapu Bulu.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Tapu Fini": ["Depois de se tornar Champion, siga para Ruins of Hope, em Poni Breaker Coast.", "Atravesse as ruínas e interaja com a estátua para encontrar Tapu Fini.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Zygarde": ["Depois de se tornar Champion, siga para Poni Island e explore os caminhos além de Poni Grove até encontrar a Resolution Cave.", "Atravesse a caverna até chegar à sala mais profunda, onde encontrará Zygarde em sua forma de 50%.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Após capturá-lo, visite a Route 16 em Ula’ula e enfrente Dexio para receber um Zygarde de 10% e o Zygarde Cube com células. Use a máquina do laboratório para trabalhar com as células e obter um Zygarde com a habilidade Power Construct."], "Cosmog": ["Depois de se tornar Champion, coloque Solgaleo na equipe e volte ao Altar of the Sunne durante a noite.", "Atravesse o portal e siga para o Lake of the Sunne. Entre no altar do lago e avance até receber Cosmog."], "Blacephalon": ["Depois de se tornar Champion, siga para Poni Grove e encontre a Ultra Recon Squad.", "Durante a investigação, procure Blacephalon na grama da área. Você poderá capturar dois deles.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Poipole": ["Depois dos acontecimentos em Ultra Megalopolis, volte ao prédio da Ultra Recon Squad e converse com seus membros.", "Ao aceitar a oferta, você receberá Poipole para acompanhar sua equipe."], "Nihilego": ["Volte ao altar de Poni Island e use o Ultra Warp Ride para viajar pelo Ultra Space.", "Procure um Ultra Wormhole branco que leve à Ultra Deep Sea. Explore a área até encontrar Nihilego.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Buzzwole": ["Volte ao altar de Poni Island e use o Ultra Warp Ride para viajar pelo Ultra Space.", "Procure um Ultra Wormhole branco que leve à Ultra Jungle. Explore a área até encontrar Buzzwole.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Xurkitree": ["Volte ao altar de Poni Island e use o Ultra Warp Ride para viajar pelo Ultra Space.", "Procure um Ultra Wormhole branco que leve à Ultra Plant. Explore a área até encontrar Xurkitree.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kartana": ["Volte ao altar de Poni Island e use o Ultra Warp Ride para viajar pelo Ultra Space.", "Procure um Ultra Wormhole branco que leve à Ultra Forest. Explore a área até encontrar Kartana.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Guzzlord": ["Volte ao altar de Poni Island e use o Ultra Warp Ride para viajar pelo Ultra Space.", "Procure um Ultra Wormhole branco que leve à Ultra Ruin. Explore a área até encontrar Guzzlord.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Articuno, Zapdos e Moltres": ["Use o Ultra Warp Ride e procure Ultra Wormholes vermelhos.", "Entre nos portais e explore os mundos até encontrar Articuno, Zapdos e Moltres. O Pokémon encontrado é aleatório, então continue viajando até encontrar os três.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Mewtwo": ["Use o Ultra Warp Ride e procure Ultra Wormholes verdes.", "Entre nos portais e explore os mundos até encontrar Mewtwo. O encontro é aleatório, então continue viajando até encontrá-lo.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Raikou e Suicune": ["Use o Ultra Warp Ride e procure Raikou em um Ultra Wormhole verde.", "Para encontrar Suicune, coloque Raikou e Entei na equipe e procure um Ultra Wormhole azul. Consiga Entei por troca ou transferência.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Ho-Oh": ["Use o Ultra Warp Ride e procure Ultra Wormholes vermelhos.", "Entre nos portais e explore os mundos até encontrar Ho-Oh. O encontro é aleatório, então continue viajando até encontrá-lo.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regirock, Regice e Registeel": ["Use o Ultra Warp Ride e procure Ultra Wormholes amarelos.", "Entre nos portais e explore as cavernas até encontrar Regirock, Regice e Registeel. O Pokémon encontrado é aleatório, então continue viajando até encontrar os três.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Latios": ["Use o Ultra Warp Ride e procure Ultra Wormholes azuis.", "Entre nos portais e explore os mundos até encontrar Latios. O encontro é aleatório, então continue viajando até encontrá-lo.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Groudon e Rayquaza": ["Use o Ultra Warp Ride e procure Groudon em um Ultr