INSERT INTO public.game (slug, caps, dicas, categorias)
SELECT pokemon.slug, guia.caps, guia.dicas, guia.categorias
FROM public.pokemon AS pokemon JOIN guias_ultra AS guia ON guia.slug = pokemon.slug
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas, categorias = EXCLUDED.categorias
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

-- Pós-game de Sword e Shield. Somente preenche registros ainda vazios.
WITH guias_galar (slug, caps, dicas, categorias) AS (
VALUES
('pokemon-sword',ARRAY['Zacian','Kubfu e Urshifu','Calyrex, Glastrier e Spectrier','Regirock','Regice','Registeel','Regieleki e Regidrago','Regigigas','Articuno de Galar','Zapdos de Galar','Moltres de Galar','Cobalion, Terrakion e Virizion','Keldeo','Articuno, Zapdos e Moltres','Mewtwo','Raikou, Entei e Suicune','Rayquaza','Uxie, Mesprit e Azelf','Heatran','Giratina','Cresselia','Landorus','Kyurem','Zygarde','Tapu Koko, Tapu Lele, Tapu Bulu e Tapu Fini','Ho-Oh','Latios','Groudon','Dialga','Tornadus','Reshiram','Xerneas','Solgaleo','Necrozma','Nihilego','Buzzwole','Pheromosa','Xurkitree','Celesteela','Kartana','Guzzlord','Stakataka','Blacephalon','Slumbering Weald','Estádios de Galar','Hop','Charmander','Type: Null','Battle Tower','Master Dojo','Expedição de Peony','Galarian Star Tournament'],'{"Zacian": ["Depois de se tornar Champion, volte à Slumbering Weald com Hop para devolver a Rusted Sword e o Rusted Shield.", "Siga os acontecimentos envolvendo Sordward e Shielbert e ajude os líderes de ginásio a enfrentar os Pokémon Dynamax fora de controle.", "Depois de resolver as ocorrências pelos estádios, siga para Hammerlocke e continue até encontrar Zacian.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kubfu e Urshifu": ["Com a expansão The Isle of Armor, vá à estação de Wedgehurst e use o Armor Pass para viajar até a ilha.", "Entre no Master Dojo e conclua os desafios de Mustard para receber Kubfu.", "Viaje pelos pontos indicados na ilha com Kubfu e fortaleça sua amizade com ele. Depois, escolha uma das duas torres e enfrente os treinadores usando Kubfu.", "Na Tower of Darkness, Kubfu evoluirá para Urshifu do estilo Single Strike. Na Tower of Waters, evoluirá para Urshifu do estilo Rapid Strike.", "Você pode concluir apenas uma das torres com esse Kubfu, então escolha a forma que deseja antes de entrar."], "Calyrex, Glastrier e Spectrier": ["Com a expansão The Crown Tundra, vá à estação de Wedgehurst e viaje até a região nevada.", "Depois de conhecer Peony e visitar Freezington, examine a estátua da cidade e ajude Calyrex a recuperar sua ligação com seu antigo companheiro.", "Converse com os moradores, obtenha sementes e escolha onde plantá-las. O campo gelado atrairá Glastrier, enquanto o campo perto do cemitério atrairá Spectrier.", "Depois dos acontecimentos em Freezington, ajude a preparar as Reins of Unity e siga até o Crown Shrine para encontrar Calyrex montado no companheiro escolhido.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo.", "Após a captura, use as Reins of Unity para separar ou unir Calyrex e seu companheiro. A escolha do campo determina qual dos dois cavalos você encontrará nessa jornada."], "Regirock": ["Na Crown Tundra, depois de receber as pistas de Peony, procure as Rock Peak Ruins em Giant’s Bed.", "Entregue uma Everstone ao primeiro Pokémon da equipe e examine a porta para abri-la. Dentro do templo, acenda os pontos no chão e interaja com a estátua para encontrar Regirock.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regice": ["Na Crown Tundra, procure as Iceberg Ruins em Snowslide Slope.", "Coloque Cryogonal na primeira posição da equipe e examine a porta para abri-la. Dentro do templo, acenda os pontos no chão e interaja com a estátua para encontrar Regice.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Registeel": ["Na Crown Tundra, procure as Iron Ruins perto de Freezington.", "Assobie diante da porta para abri-la. Dentro do templo, acenda os pontos no chão e interaja com a estátua para encontrar Registeel.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regieleki e Regidrago": ["Depois de capturar Regirock, Regice e Registeel, coloque os três na equipe e siga para as Split-Decision Ruins, em Three-Point Pass.", "Dentro do templo, acenda os pontos no chão seguindo o desenho de Regieleki ou Regidrago para escolher qual dos dois aparecerá.", "Você poderá encontrar apenas um deles nessa jornada. Para conseguir o outro, será necessário obtê-lo por troca ou transferência.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Regigigas": ["Coloque Regirock, Regice, Registeel, Regieleki e Regidrago na equipe. Como você escolhe apenas um dos dois últimos nas ruínas, será necessário conseguir o outro por troca ou transferência.", "Em Giant’s Bed, procure uma Pokémon Den cercada por pedras e interaja com ela para iniciar a batalha contra Regigigas.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Articuno de Galar": ["Depois de receber a pista de Peony, siga para Dyna Tree Hill e aproxime-se da grande árvore para encontrar as três aves de Galar.", "Após a cena, Articuno voará pela Crown Tundra. Procure-o na região e aproxime-se dele para iniciar a perseguição.", "Quando Articuno criar cópias de si mesmo, observe seus movimentos e encontre o verdadeiro para iniciar a batalha.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Zapdos de Galar": ["Depois de encontrar as três aves em Dyna Tree Hill, volte para a Wild Area de Galar.", "Procure Zapdos correndo pela região e use sua bicicleta para alcançá-lo e iniciar a batalha.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Moltres de Galar": ["Depois de encontrar as três aves em Dyna Tree Hill, viaje para a Isle of Armor.", "Procure Moltres voando pela ilha e fique em seu caminho para que ele se aproxime e inicie a batalha.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Cobalion, Terrakion e Virizion": ["Depois de encontrar Sonia na Crown Tundra, procure as pegadas espalhadas pela região.", "Reúna 50 pegadas de cada Pokémon e volte a conversar com Sonia em Freezington para descobrir suas localizações.", "Cobalion aparecerá no Frigid Sea, Terrakion na Lakeside Cave e Virizion em Giant’s Bed.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Keldeo": ["Depois de capturar Cobalion, Terrakion e Virizion, coloque os três na equipe e siga para Ballimere Lake.", "Procure uma pequena ilha com uma panela e examine as pegadas próximas. Monte o acampamento na ilha e prepare um curry com os três na equipe.", "Ao sair do acampamento, encontre Keldeo na ilha.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Articuno, Zapdos e Moltres": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avance pelas batalhas até encontrar Articuno, Zapdos e Moltres. O encontro é aleatório, então você pode precisar participar de mais aventuras.", "Salve antes de começar a aventura e prepare suas Poké Balls para a captura ao fim da batalha. Caso vença, escolha o lendário no encerramento para ficar com ele."], "Mewtwo": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avance pelas batalhas até encontrar Mewtwo. O encontro é aleatório, então você pode precisar participar de mais aventuras.", "Salve antes de começar a aventura e prepare suas Poké Balls para a captura ao fim da batalha. Caso vença, escolha o lendário no encerramento para ficar com ele."], "Raikou, Entei e Suicune": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avance pelas batalhas até encontrar Raikou, Entei e Suicune. O encontro é aleatório, então você pode precisar participar de mais aventuras.", "Salve antes de começar a aventura e prepare suas Poké Balls para a captura ao fim da batalha. Caso vença, escolha o lendário no encerramento para ficar com ele."], "Rayquaza": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avance pelas batalhas até encontrar Rayquaza. O encontro é aleatório, então você pode precisar participar de mais aventuras.", "Salve antes de começar a aventura e prepare suas Poké Balls para a captura ao fim da batalha. Caso vença, escolha o lendário no encerramento para ficar com ele."], "Uxie, Mesprit e Azelf": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avance pelas batalhas até encontrar Uxie, Mesprit e Azelf. O encontro é aleatório, então você pode precisar participar de mais aventuras.", "Salve antes de começar a aventura e prepare suas Poké Balls para a captura ao fim da batalha. Caso vença, escolha o lendário no encerramento para ficar com ele."], "Heatran": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avance pelas batalhas até encontrar Heatran. O encontro é aleatório, então você pode precisar participar de mais aventuras.", "Salve antes de começar a aventura e prepare suas Poké Balls para a captura ao fim da batalha. Caso vença, escolha o lendário no encerramento para ficar com ele."], "Giratina": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avance pelas batalhas até encontrar Giratina. O encontro é aleatório, então você pode precisar participar de mais aventuras.", "Salve antes de começar a aventura e prepare suas Poké Balls para a captura ao fim da batalha. Caso vença, escolha o lendário no encerramento para ficar com ele."], "Cresselia": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avance pelas batalhas até encontrar Cresselia. O encontro é aleatório, então você pode precisar participar de mais aventuras.", "Salve antes de começar a aventura e prepare suas Poké Balls para a captura ao fim da batalha. Caso vença, escolha o lendário no encerramento para ficar com ele."], "Landorus": ["Com a expansão The Crown Tundra, visite o Max Lair e participe das Dynamax Adventures.", "Use um Pokémon emprestado e avan