INSERT INTO public.game (slug, caps, dicas, categorias)
SELECT pokemon.slug, guia.caps, guia.dicas, guia.categorias
FROM public.pokemon AS pokemon JOIN guias_galar AS guia ON guia.slug = pokemon.slug
ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps, dicas = EXCLUDED.dicas, categorias = EXCLUDED.categorias
WHERE cardinality(public.game.caps) = 0 AND public.game.dicas = '{}'::jsonb;

-- Pós-game de Scarlet e Violet. Somente preenche registros ainda vazios.
WITH guias_paldea (slug, caps, dicas, categorias) AS (
VALUES
('pokemon-scarlet',ARRAY['Koraidon','Wo-Chien','Chien-Pao','Ting-Lu','Chi-Yu','Okidogi','Munkidori','Fezandipiti','Bloodmoon Ursaluna','Gouging Fire','Raging Bolt','Articuno','Zapdos','Moltres','Raikou','Entei','Suicune','Ho-Oh','Lugia','Latios','Latias','Groudon','Kyogre','Rayquaza','Cobalion','Terrakion','Virizion','Reshiram','Zekrom','Kyurem','Solgaleo','Lunala','Necrozma','Glastrier','Spectrier','Kubfu','Revanche dos ginásios','Academy Ace Tournament','Tera Raid Battles','The Teal Mask','The Indigo Disk','Blueberry Quests'],'{"Koraidon": ["Depois de concluir a história principal, volte à Area Zero e siga até a área mais profunda, perto da entrada do laboratório.", "Procure o segundo Koraidon no caminho próximo da estação. Esse encontro permite capturá-lo para usar na equipe.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Wo-Chien": ["Procure as oito estacas roxas espalhadas pelo sul de Paldea e retire cada uma delas do chão.", "Depois de remover todas, siga para o Grasswither Shrine, no sul de Paldea, e interaja com o santuário para encontrar Wo-Chien.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Chien-Pao": ["Procure as oito estacas amarelas espalhadas pelo oeste de Paldea e retire cada uma delas do chão.", "Depois de remover todas, siga para o Icerend Shrine, em West Province, e interaja com o santuário para encontrar Chien-Pao.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Ting-Lu": ["Procure as oito estacas verdes espalhadas pelo noroeste de Paldea e retire cada uma delas do chão.", "Depois de remover todas, siga para o Groundblight Shrine, próximo de Casseroya Lake, e interaja com o santuário para encontrar Ting-Lu.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Chi-Yu": ["Procure as oito estacas azuis espalhadas pelo nordeste de Paldea e retire cada uma delas do chão.", "Depois de remover todas, siga para o Firescourge Shrine, em North Province, e interaja com o santuário para encontrar Chi-Yu.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Okidogi": ["Depois de concluir a história de The Teal Mask e capturar Ogerpon, volte para Paradise Barrens, em Kitakami.", "Procure Okidogi no lugar onde ele foi enfrentado durante a história.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Munkidori": ["Depois de concluir a história de The Teal Mask e capturar Ogerpon, volte para Wisteria Pond, em Kitakami.", "Procure Munkidori perto do lago onde ele foi enfrentado durante a história.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Fezandipiti": ["Depois de concluir a história de The Teal Mask e capturar Ogerpon, volte para Oni Mountain, em Kitakami.", "Procure Fezandipiti após atravessar o caminho de Chilling Waterhead, na área onde ele foi enfrentado durante a história.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Bloodmoon Ursaluna": ["Em Kitakami, registre 150 Pokémon capturados na Pokédex da região e converse com Perrin em Mossui Town.", "Aceite ajudá-la e siga até Timeless Woods. Durante a investigação, fotografe os Pokémon na floresta para ajudar Perrin a encontrar a criatura misteriosa.", "Depois da investigação, encontre Bloodmoon Ursaluna.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Gouging Fire": ["Com a expansão The Indigo Disk, conclua a investigação de Bloodmoon Ursaluna em Kitakami e encontre Perrin no Terarium da Blueberry Academy.", "Registre 200 Pokémon capturados na Blueberry Pokédex e volte a falar com ela para ver as fotografias de dois Pokémon misteriosos.", "Siga para a Area Zero e procure Gouging Fire na parte mais alta da região, perto de uma antena.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Raging Bolt": ["Com a expansão The Indigo Disk, conclua a investigação de Bloodmoon Ursaluna em Kitakami e encontre Perrin no Terarium da Blueberry Academy.", "Registre 200 Pokémon capturados na Blueberry Pokédex e volte a falar com ela para ver as fotografias de dois Pokémon misteriosos.", "Siga para a Area Zero e procure Raging Bolt na parte mais profunda da área, perto da água e de uma cachoeira.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Articuno": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "O doce pode ser obtido por tarefas individuais em qualquer uma das versões.", "Depois de receber o doce de Articuno, volte para Paldea e procure-o perto de um lago entre Glaseado Mountain e Montenevera.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Zapdos": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "O doce pode ser obtido por tarefas individuais em qualquer uma das versões.", "Depois de receber o doce de Zapdos, volte para Paldea e procure-o no topo do farol perto da sua casa.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Moltres": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "O doce pode ser obtido por tarefas individuais em qualquer uma das versões.", "Depois de receber o doce de Moltres, volte para Paldea e procure-o ao norte do Asado Desert.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Raikou": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Raikou, volte para Paldea e procure-o no oeste de Paldea, perto de um pequeno lago.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Entei": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Entei, volte para Paldea e procure-o a leste de East Province, perto da costa.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Suicune": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Suicune, volte para Paldea e procure-o em uma ilha de Casseroya Lake.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Ho-Oh": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Ho-Oh, volte para Paldea e procure-o nas montanhas a leste de Alfornada.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Lugia": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Lugia, volte para Paldea e procure-o em uma pequena ilha ao norte de North Province.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Latios": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Latios, volte para Paldea e procure-o ao sul de North Province, perto de um grande lago com uma árvore.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Latias": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Latias, volte para Paldea e procure-o na praia entre Alfornada e sua casa.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Groudon": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Groudon, volte para Paldea e procure-o dentro da caverna abaixo de Alfornada.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kyogre": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Kyogre, volte para Paldea e procure-o no mar ao norte de Casseroya Lake.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Rayquaza": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "O doce de Rayquaza exige Blueberry Quests em grupo pelo Union Circle.", "Depois de receber o doce de Rayquaza, volte para Paldea e procure-o próximo da borda sudeste da Great Crater of Paldea.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Cobalion": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Cobalion, volte para Paldea e procure-o nas montanhas de North Province.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Terrakion": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Terrakion, volte para Paldea e procure-o próximo da borda oeste da Great Crater of Paldea.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Virizion": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Virizion, volte para Paldea e procure-o no nordeste de Tagtree Thicket.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Reshiram": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Reshiram, volte para Paldea e procure-o ao sul de Zapapico, próximo do rio.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Zekrom": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Zekrom, volte para Paldea e procure-o no grande planalto ao sul de Artazon.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kyurem": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "O doce de Kyurem exige Blueberry Quests em grupo pelo Union Circle.", "Depois de receber o doce de Kyurem, volte para Paldea e procure-o dentro da caverna próxima ao Pokémon Center de Dalizapa Passage.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Solgaleo": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Solgaleo, volte para Paldea e procure-o no telhado do prédio da Pokémon League.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Lunala": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Lunala, volte para Paldea e procure-o ao norte de Porto Marinada, onde o rio encontra o mar.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Necrozma": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "O doce de Necrozma exige Blueberry Quests em grupo pelo Union Circle.", "Depois de receber o doce de Necrozma, volte para Paldea e procure-o nas montanhas ao norte de Casseroya Lake.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Glastrier": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Scarlet, o doce pode vir de tarefas individuais. Em Violet, procure-o por tarefas em grupo.", "Depois de receber o doce de Glastrier, volte para Paldea e procure-o ao sul de Montenevera.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Spectrier": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "Em Violet, o doce pode vir de tarefas individuais. Em Scarlet, procure-o por tarefas em grupo.", "Depois de receber o doce de Spectrier, volte para Paldea e procure-o nas ruínas a oeste de Dalizapa Passage.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Kubfu": ["Depois de concluir The Indigo Disk, encontre Snacksworth na entrada da Blueberry Academy e conclua Blueberry Quests para receber os doces que fazem os lendários aparecerem em Paldea.", "O doce pode ser obtido por tarefas individuais em qualquer uma das versões.", "Depois de receber o doce de Kubfu, volte para Paldea e procure-o perto da cachoeira de Fury Falls, em North Province.", "Depois salve o jogo e prepare suas Poké Balls antes de enfrentá-lo."], "Revanche dos ginásios": ["Depois de concluir a história principal, converse com Geeta e aceite ajudá-la a avaliar os líderes de ginásio.", "Volte às oito cidades de ginásio e enfrente cada líder novamente. Dessa vez, eles usarão equipes mais fortes.", "Depois de vencer todos, volte à academia e conte a Geeta como foram as batalhas."], "Academy Ace Tournament": ["Depois de concluir as revanches dos ginásios, participe do torneio organizado na academia.", "Enfrente os alunos e professores até chegar à batalha final. Depois da primeira vitória, você poderá voltar para participar de novas edições."], "Tera Raid Battles": ["Depois de concluir o primeiro Academy Ace Tournament, continue participando das Tera Raid Battles até receber novas orientações sobre cristais mais perigosos.", "Ao concluir os desafios necessários, você encontrará Tera Raid Battles de seis estrelas pelo mapa de Paldea."], "The Teal Mask": ["Com a expansão The Teal Mask, viaje até Kitakami com a excursão da academia.", "Conheça Carmine e Kieran, participe do festival e investigue a história de Ogerpon e dos três Pokémon conhecidos pelos moradores como Loyal Three.", "Depois dos acontecimentos em Oni Mountain, enfrente Ogerpon e aceite sua vontade de acompanhar você."], "The Indigo Disk": ["Com a expansão The Indigo Disk, viaje até a Blueberry Academy e explore o Terarium.", "Conheça os integrantes da Blueberry League, cumpra os desafios da Elite Four e enfrente Kieran.", "Depois, acompanhe a expedição até as profundezas da Area Zero e siga a história até encontrar Terapagos."], "Blueberry Quests": ["Depois de chegar à Blueberry Academy, cumpra as tarefas chamadas Blueberry Quests enquanto explora o Terarium.", "Ganhe Blueberry Points para apoiar atividades do League Club e, depois de concluir a história de Th